#include <stdio.h>
int compute(void){int r0=14; int r1=0; int pc=0; for(int fuel=0;fuel<10;fuel++){if(pc==0){r1++;pc=1;}else if(r0>0){r0--;pc=0;}else{pc=2;break;}} return r0+r1+pc;}
int main(void){printf("%d\n", compute());return 0;}

